import java.io.*;import java.math.*;import java.security.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.util.regex.*;import java.util.stream.*;import static java.util.stream.Collectors.joining;import static java.util.stream.Collectors.toList;class Result {public static List<Integer> maxSubarray(List<Integer> arr) {int n = arr.size();int maxSubarray = arr.get(0);int currentSubarray = arr.get(0);int maxSubsequence = 0;int maxElement = arr.get(0);boolean hasPositive = false;for (int i = 0; i < n; i++) {int val = arr.get(i);if (i > 0) {currentSubarray = Math.max(val, currentSubarray + val);maxSubarray = Math.max(maxSubarray, currentSubarray);}if (val > 0) {maxSubsequence += val;hasPositive = true;}maxElement = Math.max(maxElement, val);}if (!hasPositive) {maxSubsequence = maxElement;}List<Integer> result = new ArrayList<>();result.add(maxSubarray);result.add(maxSubsequence);return result;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String line = bufferedReader.readLine();if (line != null) {int t = Integer.parseInt(line.trim());for (int i = 0; i < t; i++) {int n = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());List<Integer> result = Result.maxSubarray(arr);bufferedWriter.write(result.stream().map(Object::toString).collect(joining(" ")) + "\n");}}bufferedReader.close();bufferedWriter.close();}}